// frontend/src/context/AuthContext.js
import React, {
  createContext, useContext, useState,
  useEffect, useCallback
} from "react";
import {
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signOut,
  onAuthStateChanged,
  updateProfile,
  sendPasswordResetEmail,
  GoogleAuthProvider,
  signInWithPopup,
  deleteUser,
  reauthenticateWithCredential,
  EmailAuthProvider
} from "firebase/auth";
import {
  doc, setDoc, getDoc,
  updateDoc, serverTimestamp
} from "firebase/firestore";
import { auth, db, storage } from "../firebase/config";
import {
  ref, uploadBytesResumable,
  getDownloadURL, deleteObject
} from "firebase/storage";

const AuthContext = createContext(null);
export const useAuth = () => useContext(AuthContext);

export function AuthProvider({ children }) {
  const [user,    setUser]    = useState(null);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  // Fetch Firestore profile
  const fetchProfile = useCallback(async (uid) => {
    try {
      const snap = await getDoc(doc(db, "users", uid));
      if (snap.exists()) setProfile(snap.data());
    } catch (e) {
      console.warn("Profile fetch:", e.message);
    }
  }, []);

  // Auth state listener
  useEffect(() => {
    const unsub = onAuthStateChanged(auth, async (firebaseUser) => {
      setUser(firebaseUser);
      if (firebaseUser) await fetchProfile(firebaseUser.uid);
      else setProfile(null);
      setLoading(false);
    });
    return unsub;
  }, [fetchProfile]);

  // Sign up
  const signup = async (email, password, displayName) => {
    const { user: u } = await createUserWithEmailAndPassword(
      auth, email, password
    );
    await updateProfile(u, { displayName });
    await setDoc(doc(db, "users", u.uid), {
      displayName,
      email,
      photoURL:     null,
      organization: "",
      country:      "",
      bio:          "",
      createdAt:    serverTimestamp(),
      totalPredictions: 0
    });
    return u;
  };

  // Sign in
  const login = (email, password) =>
    signInWithEmailAndPassword(auth, email, password);

  // Google sign in
  const loginWithGoogle = async () => {
    const provider = new GoogleAuthProvider();
    const { user: u } = await signInWithPopup(auth, provider);
    const snap = await getDoc(doc(db, "users", u.uid));
    if (!snap.exists()) {
      await setDoc(doc(db, "users", u.uid), {
        displayName:  u.displayName || "",
        email:        u.email,
        photoURL:     u.photoURL || null,
        organization: "",
        country:      "",
        bio:          "",
        createdAt:    serverTimestamp(),
        totalPredictions: 0
      });
    }
    return u;
  };

  // Sign out
  const logout = () => signOut(auth);

  // Reset password
  const resetPassword = (email) => sendPasswordResetEmail(auth, email);

  // Upload profile picture
  const uploadProfilePicture = async (file) => {
    if (!user) throw new Error("Not authenticated");
    const storageRef = ref(storage, `profile-pictures/${user.uid}`);
    const snap = await uploadBytesResumable(storageRef, file);
    const url  = await getDownloadURL(snap.ref);
    await updateProfile(user, { photoURL: url });
    await updateDoc(doc(db, "users", user.uid), { photoURL: url });
    await fetchProfile(user.uid);
    return url;
  };

  // Remove profile picture
  const removeProfilePicture = async () => {
    if (!user) throw new Error("Not authenticated");
    try {
      const storageRef = ref(storage, `profile-pictures/${user.uid}`);
      await deleteObject(storageRef);
    } catch (_) {}
    await updateProfile(user, { photoURL: null });
    await updateDoc(doc(db, "users", user.uid), { photoURL: null });
    await fetchProfile(user.uid);
  };

  // Update profile
  const updateUserProfile = async (data) => {
    if (!user) throw new Error("Not authenticated");
    await updateDoc(doc(db, "users", user.uid), data);
    if (data.displayName) {
      await updateProfile(user, { displayName: data.displayName });
    }
    await fetchProfile(user.uid);
  };

  // Delete account
  const deleteAccount = async (password) => {
    if (!user) throw new Error("Not authenticated");
    const credential = EmailAuthProvider.credential(user.email, password);
    await reauthenticateWithCredential(user, credential);
    await deleteUser(user);
  };

  // Get ID token for API calls
  const getToken = () => user?.getIdToken(true);

  const value = {
    user, profile, loading,
    signup, login, loginWithGoogle,
    logout, resetPassword,
    uploadProfilePicture, removeProfilePicture,
    updateUserProfile, deleteAccount,
    getToken, fetchProfile
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}
